  --font-serif: Georgia, serif;
  --font-mono: 'JetBrains Mono', Menlo, monospace;
  --radius: .5rem;
  --shadow-2xs: 0px 1px 2px 0px hsl(220 13% 18% / 0.05);
  --shadow-xs: 0px 1px 3px 0px hsl(220 13% 18% / 0.10);
  --shadow-sm: 0px 2px 4px -1px hsl(220 13% 18% / 0.06), 0px 1px 2px -1px hsl(220 13% 18% / 0.10);
  --shadow: 0px 4px 6px -2px hsl(220 13% 18% / 0.05), 0px 2px 4px -2px hsl(220 13% 18% / 0.10);
  --shadow-md: 0px 6px 12px -2px hsl(220 13% 18% / 0.08), 0px 3px 7px -3px hsl(220 13% 18% / 0.10);
  --shadow-lg: 0px 10px 20px -5px hsl(220 13% 18% / 0.10), 0px 6px 10px -5px hsl(220 13% 18% / 0.10);
  --shadow-xl: 0px 20px 30px -10px hsl(220 13% 18% / 0.15), 0px 10px 15px -10px hsl(220 13% 18% / 0.10);
  --shadow-2xl: 0px 30px 50px -15px hsl(220 13% 18% / 0.20);
  --tracking-normal: 0em;
