  --destructive: 0 84% 35%;
  --destructive-foreground: 0 0% 98%;

  --input: 220 13% 35%;
  --ring: 234 70% 60%;

  --chart-1: 234 70% 65%;
  --chart-2: 262 52% 70%;
  --chart-3: 142 71% 60%;
  --chart-4: 234 60% 75%;
  --chart-5: 0 84% 70%;

  --shadow-2xs: 0px 1px 2px 0px hsl(0 0% 0% / 0.20);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.30);
  --shadow-sm: 0px 2px 4px -1px hsl(0 0% 0% / 0.25), 0px 1px 2px -1px hsl(0 0% 0% / 0.30);
  --shadow: 0px 4px 6px -2px hsl(0 0% 0% / 0.20), 0px 2px 4px -2px hsl(0 0% 0% / 0.30);
  --shadow-md: 0px 6px 12px -2px hsl(0 0% 0% / 0.30), 0px 3px 7px -3px hsl(0 0% 0% / 0.40);
  --shadow-lg: 0px 10px 20px -5px hsl(0 0% 0% / 0.35), 0px 6px 10px -5px hsl(0 0% 0% / 0.40);
  --shadow-xl: 0px 20px 30px -10px hsl(0 0% 0% / 0.45), 0px 10px 15px -10px hsl(0 0% 0% / 0.40);
  --shadow-2xl: 0px 30px 50px -15px hsl(0 0% 0% / 0.60);

  /* Fallback for older browsers */
  --sidebar-primary-border: hsl(var(--sidebar-primary));
  --sidebar-primary-border: hsl(from hsl(var(--sidebar-primary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  /* Fallback for older browsers */
  --sidebar-accent-border: hsl(var(--sidebar-accent));
  --sidebar-accent-border: hsl(from hsl(var(--sidebar-accent)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  /* Fallback for older browsers */
  --primary-border: hsl(var(--primary));
